//! Shared fixture for relay-core's integration tests and golden vectors.
//!
//! The keys under `tests/vectors/fixture/` are throwaway test keys generated by
//! `gen_vectors`; they protect nothing.
#![allow(dead_code)]

use std::path::{Path, PathBuf};

use relay_core::attestation::{AttestationStatement, UnsignedAttestation};
use relay_core::manifest::{DraftKey, ManifestDraft};
use relay_core::request::{RequestContext, SignedRequest, UnsignedRequest};
use relay_core::response::{Reason, UnsignedResponse};
use relay_core::seal::ReplyKey;
use relay_core::signing::SoftwareKey;
use relay_core::{Manifest, ManifestKey, Mechanism, Op, PublicKey, Role};

pub const ISSUED_AT: u64 = 1_794_700_800; // 2026-11-15T00:00:00Z
pub const VALID_UNTIL: u64 = 1_797_292_800; // 2026-12-15T00:00:00Z
pub const NOW: u64 = 1_794_744_000; // 2026-11-15T12:00:00Z
pub const SKEW: u64 = 60;
pub const TOKEN: &str = "softcard-0001";
pub const CLIENT_ID: &str = "openbao-pi5";

pub fn dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/vectors")
}

pub struct Fx {
    pub encrypt: rsa::PrivateKey,
    pub sign: SoftwareKey,
    pub auth: SoftwareKey,
    pub attest: SoftwareKey,
    /// A P-256 key the manifest does not list.
    pub rogue_attest: SoftwareKey,
    /// The P-256 ECDH `encrypt` key.
    pub ecdh: SoftwareKey,
    pub device: SoftwareKey,
    pub rogue_device: SoftwareKey,
    pub client: SoftwareKey,
    pub manifest: Manifest,
}

fn rsa_pem(k: &rsa::PrivateKey) -> String {
    rsa::pkcs8::EncodePrivateKey::to_pkcs8_pem(k, rsa::pkcs8::LineEnding::LF)
        .unwrap()
        .to_string()
}

fn rsa_from_pem(pem: &str) -> rsa::PrivateKey {
    rsa::pkcs8::DecodePrivateKey::from_pkcs8_pem(pem).unwrap()
}

fn rsa_public(k: &rsa::PrivateKey) -> PublicKey {
    let der = rsa::pkcs8::EncodePublicKey::to_public_key_der(&k.to_public_key()).unwrap();
    PublicKey::from_spki(der.as_bytes()).unwrap()
}

fn draft(fx_keys: &[(Role, &str, u8, PublicKey)], version: u64) -> ManifestDraft {
    ManifestDraft {
        version,
        issued_at: ISSUED_AT,
        valid_until: VALID_UNTIL,
        keys: fx_keys
            .iter()
            .map(|(role, label, id, pk)| DraftKey {
                role: *role,
                label: label.to_string(),
                id: vec![*id],
                token: TOKEN.into(),
                public_key: pk.clone(),
                hardware_attestation: None,
            })
            .collect(),
    }
}

/// Write fresh fixture keys and the three manifests the OpenPGP script signs.
pub fn generate_fixture() {
    let d = dir().join("fixture");
    std::fs::create_dir_all(&d).unwrap();
    let mut rng = rand_core::UnwrapErr(getrandom::SysRng);
    let encrypt = rsa::PrivateKey::new(&mut rng, 2048).unwrap();
    std::fs::write(d.join("encrypt.pem"), rsa_pem(&encrypt)).unwrap();
    for name in [
        "sign",
        "auth",
        "attest",
        "rogue-attest",
        "ecdh",
        "device",
        "rogue-device",
    ] {
        std::fs::write(
            d.join(format!("{name}.pem")),
            &*SoftwareKey::generate_p256().to_pkcs8_pem().unwrap(),
        )
        .unwrap();
    }
    std::fs::write(
        d.join("client.pem"),
        &*SoftwareKey::generate_ed25519().to_pkcs8_pem().unwrap(),
    )
    .unwrap();
    let fx = load_keys();
    let keys = manifest_keys(&fx.0, &fx.1, &fx.2, &fx.3);
    std::fs::write(d.join("manifest.json"), draft(&keys, 1).to_json().unwrap()).unwrap();
    std::fs::write(
        d.join("manifest-v2.json"),
        draft(&keys[..3], 2).to_json().unwrap(),
    )
    .unwrap();
    // Same version as manifest.json, different bytes (no attest key).
    std::fs::write(
        d.join("manifest-v1-alt.json"),
        draft(&keys[..3], 1).to_json().unwrap(),
    )
    .unwrap();
}

fn manifest_keys(
    e: &rsa::PrivateKey,
    s: &SoftwareKey,
    a: &SoftwareKey,
    at: &SoftwareKey,
) -> Vec<(Role, &'static str, u8, PublicKey)> {
    vec![
        (Role::Encrypt, "openbao-unseal", 1, rsa_public(e)),
        (Role::Sign, "code-signing", 2, s.public_key()),
        (Role::Auth, "ssh", 3, a.public_key()),
        (Role::Attest, "attest", 4, at.public_key()),
        (Role::Encrypt, "ecdh", 5, ecdh_key().public_key()),
    ]
}

fn read(name: &str) -> String {
    std::fs::read_to_string(dir().join("fixture").join(name))
        .unwrap_or_else(|e| panic!("fixture {name}: {e}"))
}

/// The P-256 ECDH `encrypt` key (a software stand-in for the card's).
fn ecdh_key() -> SoftwareKey {
    SoftwareKey::from_pkcs8_pem(&read("ecdh.pem")).unwrap()
}

fn load_keys() -> (rsa::PrivateKey, SoftwareKey, SoftwareKey, SoftwareKey) {
    let p = |n| SoftwareKey::from_pkcs8_pem(&read(n)).unwrap();
    (
        rsa_from_pem(&read("encrypt.pem")),
        p("sign.pem"),
        p("auth.pem"),
        p("attest.pem"),
    )
}

pub fn load() -> Fx {
    let p = |n| SoftwareKey::from_pkcs8_pem(&read(n)).unwrap();
    let (encrypt, sign, auth, attest) = load_keys();
    let manifest = Manifest::from_json_unverified(read("manifest.json").as_bytes()).unwrap();
    Fx {
        encrypt,
        sign,
        auth,
        attest,
        rogue_attest: p("rogue-attest.pem"),
        ecdh: p("ecdh.pem"),
        device: p("device.pem"),
        rogue_device: p("rogue-device.pem"),
        client: p("client.pem"),
        manifest,
    }
}

impl Fx {
    pub fn key(&self, role: Role) -> &ManifestKey {
        self.manifest.keys.iter().find(|k| k.role == role).unwrap()
    }

    pub fn attestation_with(
        &self,
        signer: &SoftwareKey,
        device: &SoftwareKey,
        nb: u64,
        na: u64,
    ) -> AttestationStatement {
        let st = UnsignedAttestation::new(
            "test-device",
            device.public_key(),
            nb,
            na,
            signer.public_key().fingerprint().clone(),
        )
        .unwrap();
        let sig = signer.sign(&st.to_be_signed());
        st.with_signature(sig)
    }

    pub fn attestation(&self) -> AttestationStatement {
        self.attestation_with(&self.attest, &self.device, ISSUED_AT, VALID_UNTIL)
    }

    pub fn request(
        &self,
        role: Role,
        op: Op,
        mechanism: Mechanism,
        input: Vec<u8>,
    ) -> (SignedRequest, ReplyKey) {
        let reply = ReplyKey::generate();
        let ctx = RequestContext {
            host: "pi5.tailnet".into(),
            purpose: "OpenBao unseal on pi5".into(),
            consumer: "bao".into(),
        };
        let r = UnsignedRequest::new(
            CLIENT_ID,
            self.key(role),
            op,
            mechanism,
            input,
            ctx,
            reply.public_bytes(),
            NOW,
            NOW + 90,
        )
        .unwrap();
        let sig = self.client.sign(&r.to_be_signed());
        (r.with_signature(sig), reply)
    }

    /// A decrypt request for an OAEP ciphertext of `plaintext`.
    pub fn decrypt_request(&self, plaintext: &[u8]) -> (SignedRequest, ReplyKey) {
        let mut rng = rand_core::UnwrapErr(getrandom::SysRng);
        let ct = self
            .encrypt
            .to_public_key()
            .encrypt(&mut rng, rsa::Oaep::<sha2::Sha256>::new(), plaintext)
            .unwrap();
        self.request(
            Role::Encrypt,
            Op::Decrypt,
            Mechanism::RsaPkcsOaep { label: vec![] },
            ct,
        )
    }

    /// A `sign`-role ECDSA-SHA256 request and the correct signature result.
    pub fn key_by_label(&self, label: &str) -> &ManifestKey {
        self.manifest
            .keys
            .iter()
            .find(|k| k.label == label)
            .unwrap()
    }

    /// An ECDH request on the `ecdh` key from a fresh peer key, and the derived result the
    /// approver would return (computed here in software).
    pub fn derive_request(
        &self,
        kdf: u64,
        shared: &[u8],
        out_len: u32,
    ) -> (SignedRequest, ReplyKey, Vec<u8>) {
        let SoftwareKey::P256(card) = &self.ecdh else {
            panic!("ecdh key is P-256")
        };
        let peer = SoftwareKey::generate_p256();
        let SoftwareKey::P256(peer_sk) = &peer else {
            unreachable!()
        };
        let peer_point = peer.public_key().ec_point().unwrap();
        let secret = p256::ecdh::diffie_hellman(
            peer_sk.as_nonzero_scalar(),
            card.verifying_key().as_affine(),
        );
        let mech = Mechanism::ecdh_from_pkcs11(kdf, shared.to_vec(), out_len).unwrap();
        let result = match kdf {
            relay_core::mechanism::ckm::CKD_NULL => {
                secret.raw_secret_bytes()[..out_len as usize].to_vec()
            }
            _ => {
                let mut out = vec![0u8; out_len as usize];
                ansi_x963_kdf::derive_key_into::<sha2::Sha256>(
                    secret.raw_secret_bytes(),
                    shared,
                    &mut out,
                )
                .unwrap();
                out
            }
        };
        let reply = ReplyKey::generate();
        let ctx = RequestContext {
            host: "pi5.tailnet".into(),
            purpose: "ECDH".into(),
            consumer: "test".into(),
        };
        let r = UnsignedRequest::new(
            CLIENT_ID,
            self.key_by_label("ecdh"),
            Op::Derive,
            mech,
            peer_point,
            ctx,
            reply.public_bytes(),
            NOW,
            NOW + 90,
        )
        .unwrap();
        let sig = self.client.sign(&r.to_be_signed());
        (r.with_signature(sig), reply, result)
    }

    pub fn sign_request(&self, msg: &[u8]) -> (SignedRequest, ReplyKey, Vec<u8>) {
        let (r, k) = self.request(Role::Sign, Op::Sign, Mechanism::EcdsaSha256, msg.to_vec());
        (r, k, self.sign.sign(msg).to_vec())
    }

    pub fn approve(
        &self,
        req: &SignedRequest,
        result: &[u8],
        att: &AttestationStatement,
        device: &SoftwareKey,
    ) -> Vec<u8> {
        let r = UnsignedResponse::approved(req, result, att, NOW + 30).unwrap();
        let sig = device.sign(&r.to_be_signed());
        r.with_signature(sig).bytes().to_vec()
    }

    pub fn deny(&self, req: &SignedRequest, reason: Option<Reason>) -> Vec<u8> {
        let att = self.attestation();
        let r = UnsignedResponse::denied(req, reason, &att, NOW + 30);
        let sig = self.device.sign(&r.to_be_signed());
        r.with_signature(sig).bytes().to_vec()
    }

    pub fn error(&self, req: &SignedRequest, reason: Option<Reason>) -> Vec<u8> {
        let att = self.attestation();
        let r = UnsignedResponse::error(req, reason, &att, NOW + 30);
        let sig = self.device.sign(&r.to_be_signed());
        r.with_signature(sig).bytes().to_vec()
    }
}
